    // Home Page - About Us section
    "About Us Paragraph 1": "في شركة سكيل ماونت لتجارة الإلكترونيات ذ.م.م، نؤمن بأن تجربة المشاهدة الخاصة بك يجب أن تكون سلسة وآمنة وعصرية. وبصفتنا رواداً في حلول إعداد الترفيه، فإننا نتجاوز مجرد توريد الأجهزة بل نهندس الدقة والموثوقية في كل منتج.",
    "About Us Paragraph 2": "إن التزامنا بالتميز والابتكار يدفع بمجموعتنا من تقنيات التركيب، بدءاً من حوامل شاشات التلفزيون LCD الثابتة والمتحركة المتينة ووصولاً إلى الأنظمة الميكانيكية المتقدمة وحلول جدران الفيديو. كما نقدم كراسي ألعاب مريحة ومكاتب وإكسسوارات ممتازة مثل الكابلات والأسلاك عالية الجودة - وكلها مصممة لدعم وتحسين إعداداتك الإلكترونية.",
    "About Us Paragraph 3": "ثق في سكيل تيك (Skill Tech) لتوفير القوة والاستقرار والأناقة التي ترتقي بمساحتك.",
    "Read more": "اقرأ المزيد",
