    // Home Page - Services
    "TV Installation Service": "خدمة تركيب التلفزيون",
    "TV Installation Description 1": "هل تبحث عن خدمات تركيب تلفزيونات موثوقة؟ يوفر فريق الخبراء لدينا خدمات تركيب احترافية للتلفزيونات المثبتة على الحائط أو الحوامل لجميع الأحجام والعلامات التجارية. من التركيب الدقيق إلى إدارة الكابلات النظيفة، نضمن لك تشطيباً خالياً من العيوب في كل مرة.",
    "TV Installation Description 2": "نتعامل مع تلفزيونات LED و OLED و 4K والمنحنية بعناية فائقة — لخدمة المساحات السكنية والتجارية على حد سواء. استمتع بخدمة في نفس اليوم، وأسعار تنافسية، ورضا مضمون.",
    "TV Installation Description 3": "احجز خدمة التركيب الخاصة بك اليوم — حدد موعداً عبر الإنترنت أو اتصل بنا للحصول على مساعدة سريعة.",
