    // Privacy Policy Page
    "Privacy Policy - Skill Tech": "سياسة الخصوصية - سكيل تيك",
    "Privacy Policy for Skill Tech Group of Companies.": "سياسة الخصوصية لمجموعة شركات سكيل تيك.",
    "Effective Date: July 20, 2026": "تاريخ النفاذ: 20 يوليو 2026",
    "At Skill Tech Group of Companies, we are committed to protecting your privacy and safeguarding the personal information you share with us. This Privacy Policy explains how we collect, use, store, and protect your information when you visit www.skilltechonline.com or interact with our services.": "في مجموعة شركات سكيل تيك، نحن ملتزمون بحماية خصوصيتك وضمان سلامة المعلومات الشخصية التي تشاركها معنا. توضح سياسة الخصوصية هذه كيفية جمع معلوماتك واستخدامها وتخزينها وحمايتها عند زيارتك للموقع www.skilltechonline.com أو التفاعل مع خدماتنا.",
    "1. Information We Collect": "1. المعلومات التي نجمعها",
    "We may collect personal information that you voluntarily provide through our website, including:": "قد نجمع معلومات شخصية تقدمها لنا طواعية من خلال موقعنا الإلكتروني، بما في ذلك:",
    "Full Name": "الاسم الكامل",
