    "Installation Booking Information": "معلومات حجز التركيب",
    "Job Application Details and Uploaded CV": "تفاصيل طلب الوظيفة والسيرة الذاتية المرفوعة",
    "Any other information you choose to provide": "أي معلومات أخرى تختار تقديمها",
    "2. How We Use Your Information": "2. كيف نستخدم معلوماتك",
    "Your information is used to:": "تُستخدم معلوماتك في:",
    "Respond to enquiries and customer support requests.": "الرد على الاستفسارات وطلبات دعم العملاء.",
    "Process installation bookings and service requests.": "معالجة حجوزات التركيب وطلبات الخدمة.",
    "Provide product information and quotations.": "تقديم معلومات المنتجات وعروض الأسعار.",
    "Review and manage job applications.": "مراجعة وإدارة طلبات التوظيف.",
    "Improve our website, products, and services.": "تحسين موقعنا الإلكتروني ومنتجاتنا وخدماتنا.",
    "Communicate important updates when necessary.": "التواصل بشأن التحديثات الهامة عند الضرورة.",
    "Comply with applicable legal obligations.": "الامتثال للالتزامات القانونية المعمول بها.",
    "3. Information Sharing": "3. مشاركة المعلومات",
    "We respect your privacy and do not sell, rent, or trade your personal information. Your information may only be shared with trusted service providers or government authorities when required by law or for the purpose of delivering our services.": "نحن نحترم خصوصيتك ولا نبيع معلوماتك الشخصية أو نؤجرها أو نتاجر بها. قد يتم مشاركة معلوماتك فقط مع مقدمي الخدمات الموثوقين أو السلطات الحكومية عندما يقتضي القانون ذلك أو لغرض تقديم خدماتنا.",
    "4. Data Security": "4. أمن البيانات",
    "We implement appropriate technical and organizational measures to protect your personal information against unauthorized access, misuse, alteration, or disclosure. While we strive to safeguard your data, no internet transmission or electronic storage method can be guaranteed to be completely secure.": "نحن ننفذ تدابير تقنية وتنظيمية مناسبة لحماية معلوماتك الشخصية من الوصول غير المصرح به أو سوء الاستخدام أو التعديل أو الإفشاء. ورغم سعينا لحماية بياناتك، فإنه لا يمكن ضمان أمن أي وسيلة نقل عبر الإنترنت أو طريقة تخزين إلكترونية بنسبة 100%.",
    "5. Cookies": "5. ملفات تعريف الارتباط (Cookies)",
    "Our website may use cookies and similar technologies to improve your browsing experience, analyze website traffic, and enhance website functionality. You can manage or disable cookies through your browser settings at any time.": "قد يستخدم موقعنا ملفات تعريف الارتباط وتقنيات مشابهة لتحسين تجربة التصفح الخاصة بك، وتحليل حركة مرور الموقع، وتعزيز وظائف الموقع. يمكنك إدارة أو تعطيل ملفات تعريف الارتباط من خلال إعدادات المتصفح الخاص بك في أي وقت.",
    "6. Third-Party Links": "6. روابط الأطراف الثالثة",
    "Our website may contain links to external websites for your convenience. We are not responsible for the privacy practices or content of these third-party websites and encourage you to review their respective privacy policies.": "قد يحتوي موقعنا على روابط لمواقع خارجية لراحتك. نحن لسنا مسؤولين عن ممارسات الخصوصية أو محتوى هذه المواقع الخارجية ونشجعك على مراجعة سياسات الخصوصية الخاصة بها.",
    "7. Your Rights": "7. حقوقك",
    "You may request access to, correction of, or deletion of your personal information, subject to applicable laws. To make such a request, please contact us using the details below.": "يمكنك طلب الوصول إلى معلوماتك الشخصية أو تصحيحها أو حذفها، وذلك وفقاً للقوانين المعمول بها. لتقديم مثل هذا الطلب، يرجى الاتصال بنا باستخدام التفاصيل أدناه.",
    "8. Changes to This Policy": "8. تغييرات على هذه السياسة",
    "We may update this Privacy Policy from time to time. Any changes will be posted on this page with the revised effective date.": "قد نقوم بتحديث سياسة الخصوصية هذه من وقت لآخر. وسيتم نشر أي تغييرات على هذه الصفحة مع تاريخ النفاذ المعدل.",
    "9. Contact Us": "9. اتصل بنا",
    "If you have any questions regarding this Privacy Policy or how we handle your personal information, please contact us:": "إذا كانت لديك أي أسئلة بخصوص سياسة الخصوصية هذه أو كيفية تعاملنا مع معلوماتك الشخصية، يرجى الاتصال بنا:",
    "Website: www.skilltechonline.com": "الموقع الإلكتروني: www.skilltechonline.com",
