    // Home Page - About Us section
    "About Us Paragraph 1": "En SKILL MOUNT ELECTRONICS TRADING LLC, creemos que su experiencia de visualización debe ser fluida, segura y elegante. Como pioneros en soluciones de entretenimiento, vamos más allá del suministro de hardware: diseñamos precisión y confiabilidad en cada producto.",
    "About Us Paragraph 2": "Nuestro compromiso con la excelencia y la innovación impulsa nuestra gama de tecnologías de montaje, desde soportes de pared fijos y articulados duraderos para TV LCD hasta sistemas motorizados avanzados y soluciones de video wall. También ofrecemos sillas y escritorios ergonómicos para juegos, y accesorios premium como cables y alambres de alta calidad, todos diseñados para respaldar y mejorar su configuración electrónica.",
    "About Us Paragraph 3": "Confíe en Skill Tech para brindar la fuerza, estabilidad y sofisticación que elevan su espacio.",
