    "Build your career with a leader in display mounting solutions. We are looking for talented individuals to grow with us.": "Construya su carrera con un líder en soluciones de montaje de pantallas. Buscamos personas talentosas para crecer con nosotros.",
    "Privacy Policy for Skill Tech Group of Companies.": "Política de privacidad para Skill Tech Group of Companies.",
    "Effective Date: July 20, 2026": "Fecha de entrada en vigor: 20 de julio de 2026",
    "At Skill Tech Group of Companies, we are committed to protecting your privacy and safeguarding the personal information you share with us. This Privacy Policy explains how we collect, use, store, and protect your information when you visit www.skilltechonline.com or interact with our services.": "En Skill Tech Group of Companies, estamos comprometidos a proteger su privacidad y salvaguardar la información personal que comparte con nosotros. Esta Política de privacidad explica cómo recopilamos, utilizamos, almacenamos y protegemos su información cuando visita www.skilltechonline.com o interactúa con nuestros servicios.",
    "1. Information We Collect": "1. Información que recopilamos",
    "We may collect personal information that you voluntarily provide through our website, including:": "Podemos recopilar información personal que usted proporcione voluntariamente a través de nuestro sitio web, incluyendo:",
    "Service or Product Enquiry Details": "Detalles de consultas sobre productos o servicios",
