    "2. How We Use Your Information": "2. Cómo utilizamos su información",
    "Your information is used to:": "Su información se utiliza para:",
    "Respond to enquiries and customer support requests.": "Responder a consultas y solicitudes de atención al cliente.",
    "Process installation bookings and service requests.": "Procesar reservas de instalación y solicitudes de servicio.",
    "Provide product information and quotations.": "Proporcionar información sobre productos y presupuestos.",
    "Review and manage job applications.": "Revisar y gestionar solicitudes de empleo.",
    "Improve our website, products, and services.": "Mejorar nuestro sitio web, productos y servicios.",
    "Communicate important updates when necessary.": "Comunicar actualizaciones importantes cuando sea necesario.",
    "Comply with applicable legal obligations.": "Cumplir con las obligaciones legales aplicables.",
    "3. Information Sharing": "3. Intercambio de información",
    "We respect your privacy and do not sell, rent, or trade your personal information. Your information may only be shared with trusted service providers or government authorities when required by law or for the purpose of delivering our services.": "Respetamos su privacidad y no vendemos, alquilamos ni intercambiamos su información personal. Su información solo puede compartirse con proveedores de servicios de confianza o autoridades gubernamentales cuando lo exija la ley o con el fin de prestar nuestros servicios.",
    "4. Data Security": "4. Seguridad de los datos",
    "We implement appropriate technical and organizational measures to protect your personal information against unauthorized access, misuse, alteration, or disclosure. While we strive to safeguard your data, no internet transmission or electronic storage method can be guaranteed to be completely secure.": "Implementamos medidas técnicas y organizativas adecuadas para proteger su información personal contra el acceso no autorizado, el uso indebido, la alteración o la divulgación. Aunque nos esforzamos por salvaguardar sus datos, ningún método de transmisión por Internet o de almacenamiento electrónico puede garantizarse como completamente seguro.",
    "5. Cookies": "5. Cookies",
    "Our website may use cookies and similar technologies to improve your browsing experience, analyze website traffic, and enhance website functionality. You can manage or disable cookies through your browser settings at any time.": "Nuestro sitio web puede utilizar cookies y tecnologías similares para mejorar su experiencia de navegación, analizar el tráfico del sitio web y mejorar la funcionalidad del mismo. Puede gestionar o desactivar las cookies a través de la configuración de su navegador en cualquier momento.",
    "6. Third-Party Links": "6. Enlaces de terceros",
    "Our website may contain links to external websites for your convenience. We are not responsible for the privacy practices or content of these third-party websites and encourage you to review their respective privacy policies.": "Nuestro sitio web puede contener enlaces a sitios web externos para su comodidad. No somos responsables de las prácticas de privacidad ni del contenido de estos sitios web de terceros y le recomendamos que revise sus respectivas políticas de privacidad.",
    "7. Your Rights": "7. Sus derechos",
    "You may request access to, correction of, or deletion of your personal information, subject to applicable laws. To make such a request, please contact us using the details below.": "Puede solicitar el acceso, la corrección o la eliminación de su información personal, sujeto a las leyes aplicables. Para realizar dicha solicitud, póngase en contacto con nosotros utilizando los detalles a continuación.",
    "8. Changes to This Policy": "8. Cambios en esta política",
    "We may update this Privacy Policy from time to time. Any changes will be posted on this page with the revised effective date.": "Podemos actualizar esta Política de privacidad periódicamente. Cualquier cambio se publicará en esta página con la fecha de entrada en vigor revisada.",
    "9. Contact Us": "9. Contáctenos",
    "If you have any questions regarding this Privacy Policy or how we handle your personal information, please contact us:": "Si tiene alguna pregunta sobre esta Política de privacidad o sobre cómo manejamos su información personal, contáctenos:",
