    // Home Page - About Us section
    "About Us Paragraph 1": "Na SKILL MOUNT ELECTRONICS TRADING LLC, acreditamos que sua experiência visual deve ser perfeita, segura e elegante. Como pioneiros em soluções de entretenimento, vamos além do fornecimento de hardware: projetamos precisão e confiabilidade em cada produto.",
    "About Us Paragraph 2": "Nosso compromisso com a excelência e a inovação impulsiona nossa linha de tecnologias de montagem, desde suportes de parede fixos e articulados para TVs LCD até sistemas motorizados avançados e soluções de video wall. Também oferecemos cadeiras e mesas ergonômicas para jogos, e acessórios premium como cabos e fios de alta qualidade, todos projetados para apoiar e aprimorar seus equipamentos eletrônicos.",
    "About Us Paragraph 3": "Confie na Skill Tech para fornecer a resistência, a estabilidade e a sofisticação que elevam o seu espaço.",
