    "TV Installation Service": "Serviço de Instalação de TV",
    "TV Installation Description 1": "Procurando serviços confiáveis de instalação de TV? Nossa equipe especializada oferece montagens profissionais em parede e em suportes de chão para todos os tamanhos e marcas. Da instalação precisa ao gerenciamento limpo de cabos, garantimos um acabamento impecável sempre.",
    "TV Installation Description 2": "Atendemos TVs LED, OLED, 4K e curvas com cuidado profissional, tanto para residências quanto para ambientes comerciais. Desfrute de atendimento no mesmo dia, preços competitivos e satisfação garantida.",
    "TV Installation Description 3": "Agende sua instalação hoje mesmo: agende online ou ligue para nós para obter assistência rápida.",
