    "Top 5 AV Solutions for Modern Workspaces": "As 5 Principais Soluções AV para Ambientes de Trabalho Modernos",
    "Ergonomic Mounts: Enhance Comfort, Productivity & Modern Workspaces": "Suportes Ergonômicos: Aumente o Conforto, Produtividade e Espaços Modernos",
    "How to Choose the Right TV Mount for Your Space": "Como Escolher o Suporte de TV Ideal para o Seu Espaço",

    // Service Page
    "TV Installation Service": "Serviço de Instalação de TV",
    "Looking for reliable TV installation services? Our expert team provides professional wall mounted and stand mounted TV setups for all sizes and brands. From precise mounting to clean cable management, we ensure a flawless finish every time. We handle LED, OLED, 4K, and curved TVs with expert care serving both residential and commercial spaces. Enjoy same day service, competitive pricing, and guaranteed satisfaction. Book your installation today schedule online or call us for quick assistance.": "Procurando serviços confiáveis de instalação de TV? Nossa equipe especializada oferece montagens profissionais de TVs em paredes e suportes para todos os tamanhos e marcas. Da fixação precisa à organização impecável de cabos, garantimos um acabamento perfeito. Agende sua instalação online hoje mesmo ou ligue para nós.",
    "TV Mounting Service": "Serviço de Montagem de TV",
    "We provide reliable TV wall mounting solutions with strong, durable brackets and expert installation techniques. Every installation follows strict safety standards, ensuring stability, optimal viewing angles, and a clutter free appearance.": "Oferecemos soluções confiáveis de montagem de TV na parede com suportes robustos e técnicas avançadas de instalação, garantindo estabilidade, ângulos de visão ideais e um visual organizado.",
    "Experience hassle free and secure TV mounting with our expert technicians. We ensure perfect wall placement, safe installation, and clean cable management for a seamless viewing setup in your home or office.": "Tenha uma instalação de TV tranquila e segura com nossos técnicos qualificados. Garantimos posicionamento ideal na parede e organização total de cabos em sua casa ou escritório.",
    "Install Services": "Serviços de Instalação",
