    // Service Page
    "TV Installation Service": "Service d'Installation TV",
    "Looking for reliable TV installation services? Our expert team provides professional wall mounted and stand mounted TV setups for all sizes and brands. From precise mounting to clean cable management, we ensure a flawless finish every time. We handle LED, OLED, 4K, and curved TVs with expert care serving both residential and commercial spaces. Enjoy same day service, competitive pricing, and guaranteed satisfaction. Book your installation today schedule online or call us for quick assistance.": "Vous recherchez un service d'installation de TV fiable ? Notre équipe d'experts assure l'installation professionnelle de téléviseurs muraux ou sur pied pour toutes marques et tailles. Du montage précis au passage soigné des câbles, nous garantissons une finition impeccable. Réservez votre installation dès aujourd'hui.",
    "TV Mounting Service": "Service de Fixation TV",
    "We provide reliable TV wall mounting solutions with strong, durable brackets and expert installation techniques. Every installation follows strict safety standards, ensuring stability, optimal viewing angles, and a clutter free appearance.": "Nous proposons des solutions fiables de fixation murale pour téléviseurs avec des supports robustes et des techniques d'installation expertes, garantissant sécurité, stabilité et angles de vision optimaux.",
    "Experience hassle free and secure TV mounting with our expert technicians. We ensure perfect wall placement, safe installation, and clean cable management for a seamless viewing setup in your home or office.": "Profitez d'une installation TV sécurisée et sans tracas avec nos techniciens qualifiés dans votre maison ou votre bureau.",
    "Install Services": "Services d'Installation",
    "Mount Services": "Services de Fixation",
    "Book Now": "Réserver Maintenant",
    "Retail / Residential": "Commerce / Résidentiel",
    "Commercial / Hospitality": "Commercial / Hôtellerie",
    "Video wall / Others": "Mur Vidéo / Autres",

    // Home Page - About Us & Descriptions
    "About Us Paragraph 1": "Chez SKILL MOUNT ELECTRONICS TRADING LLC, nous croyons que votre expérience visuelle doit être fluide, sécurisée et élégante. En tant que pionniers des solutions d'installation audiovisuelle, nous allons au-delà de la simple fourniture de matériel : nous intégrons précision et fiabilité dans chaque produit.",
    "About Us Paragraph 2": "Notre engagement envers l'excellence et l'innovation guide notre gamme de technologies de fixation, des supports muraux LCD fixes et articulés durables aux systèmes motorisés avancés et solutions de murs vidéo. Nous proposons également des bureaux et chaises gaming ergonomiques, ainsi que des accessoires haut de gamme tels que des câbles et fils de haute qualité conçus pour améliorer votre installation électronique.",
    "About Us Paragraph 3": "Faites confiance à Skill Tech pour apporter la solidité, la stabilité et le raffinement qui mettront en valeur votre espace.",
    "Read more": "Lire la suite",
    "Read less": "Lire moins",

