    // Home Page - Services Section
    "TV Installation Description 1": "Vous recherchez un service d'installation de TV fiable ? Notre équipe d'experts assure des installations professionnelles sur support mural ou sur pied pour toutes tailles et marques. Du positionnement précis à la gestion soignée des câbles, nous garantissons une finition impeccable à chaque fois.",
    "TV Installation Description 2": "Nous prenons en charge les téléviseurs LED, OLED, 4K et incurvés avec un soin expert — tant pour les espaces résidentiels que commerciaux. Bénéficiez d'un service le jour même, de tarifs compétitifs et d'une satisfaction garantie.",
    "TV Installation Description 3": "Réservez votre installation dès aujourd'hui — planifiez en ligne ou appelez-nous pour une assistance rapide.",

