    // Privacy Policy Page
    "Privacy Policy for Skill Tech Group of Companies.": "Politique de confidentialité pour Skill Tech Group of Companies.",
    "Effective Date: July 20, 2026": "Date d'entrée en vigueur : 20 juillet 2026",
    "At Skill Tech Group of Companies, we are committed to protecting your privacy and safeguarding the personal information you share with us. This Privacy Policy explains how we collect, use, store, and protect your information when you visit www.skilltechonline.com or interact with our services.": "Chez Skill Tech Group of Companies, nous nous engageons à protéger votre vie privée et à sécuriser les informations personnelles que vous partagez avec nous. Cette Politique de Confidentialité explique comment nous collectons, utilisons, stockons et protégeons vos informations lorsque vous visitez www.skilltechonline.com ou interagissez avec nos services.",
    "1. Information We Collect": "1. Informations Que Nous Collectons",
    "We may collect personal information that you voluntarily provide through our website, including:": "Nous pouvons collecter des informations personnelles que vous fournissez volontairement via notre site Web, notamment :",
    "Service or Product Enquiry Details": "Détails de la demande de produit ou de service",
    "Installation Booking Information": "Informations de réservation d'installation",
    "Job Application Details and Uploaded CV": "Détails de la candidature et CV téléchargé",
    "Any other information you choose to provide": "Toute autre information que vous choisissez de fournir",
    "2. How We Use Your Information": "2. Comment Nous Utilisons Vos Informations",
    "Your information is used to:": "Vos informations sont utilisées pour :",
    "Respond to enquiries and customer support requests.": "Répondre aux demandes de renseignements et d'assistance client.",
    "Process installation bookings and service requests.": "Traiter les réservations d'installation et les demandes de service.",
    "Provide product information and quotations.": "Fournir des informations sur les produits et des devis.",
    "Review and manage job applications.": "Examiner et gérer les candidatures.",
    "Improve our website, products, and services.": "Améliorer notre site Web, nos produits et nos services.",
    "Communicate important updates when necessary.": "Communiquer des mises à jour importantes si nécessaire.",
    "Comply with applicable legal obligations.": "Se conformer aux obligations légales en vigueur.",
    "3. Information Sharing": "3. Partage des Informations",
    "We respect your privacy and do not sell, rent, or trade your personal information. Your information may only be shared with trusted service providers or government authorities when required by law or for the purpose of delivering our services.": "Nous respectons votre vie privée et ne vendons, ne louons ni n'échangeons vos informations personnelles. Vos informations peuvent uniquement être partagées avec des prestataires de confiance ou des autorités gouvernementales lorsque la loi l'exige ou pour la fourniture de nos services.",
    "4. Data Security": "4. Sécurité des Données",
    "We implement appropriate technical and organizational measures to protect your personal information against unauthorized access, misuse, alteration, or disclosure. While we strive to safeguard your data, no internet transmission or electronic storage method can be guaranteed to be completely secure.": "Nous mettons en œuvre des mesures techniques et organisationnelles appropriées pour protéger vos informations personnelles contre tout accès non autorisé, utilisation abusive, altération ou divulgation. Bien que nous nous efforcions de protéger vos données, aucune transmission sur Internet ne peut être garantie comme totalement sécurisée.",
    "5. Cookies": "5. Cookies",
    "Our website may use cookies and similar technologies to improve your browsing experience, analyze website traffic, and enhance website functionality. You can manage or disable cookies through your browser settings at any time.": "Notre site Web peut utiliser des cookies et des technologies similaires pour améliorer votre expérience de navigation, analyser le trafic du site et optimiser ses fonctionnalités. Vous pouvez gérer ou désactiver les cookies à tout moment dans les paramètres de votre navigateur.",
    "6. Third-Party Links": "6. Liens Tiers",
    "Our website may contain links to external websites for your convenience. We are not responsible for the privacy practices or content of these third-party websites and encourage you to review their respective privacy policies.": "Notre site Web peut contenir des liens vers des sites Web externes pour votre commodité. Nous ne sommes pas responsables des pratiques de confidentialité ou du contenu de ces sites tiers et vous encourageons à consulter leurs politiques de confidentialité respectives.",
    "7. Your Rights": "7. Vos Droits",
    "You may request access to, correction of, or deletion of your personal information, subject to applicable laws. To make such a request, please contact us using the details below.": "Vous pouvez demander l'accès à vos données personnelles, leur rectification ou leur suppression, conformément aux lois applicables. Pour faire une telle demande, veuillez nous contacter aux coordonnées ci-dessous.",
    "8. Changes to This Policy": "8. Modifications de Cette Politique",
    "We may update this Privacy Policy from time to time. Any changes will be posted on this page with the revised effective date.": "Nous pouvons mettre à jour cette Politique de Confidentialité de temps à autre. Tout changement sera publié sur cette page avec la date de révision.",
    "9. Contact Us": "9. Contactez-Nous",
    "If you have any questions regarding this Privacy Policy or how we handle your personal information, please contact us:": "Si vous avez des questions concernant cette Politique de Confidentialité ou le traitement de vos informations personnelles, veuillez nous contacter :",
    "Website: www.skilltechonline.com": "Site Web : www.skilltechonline.com",
    "Email: info@skilltechonline.com": "E-mail : info@skilltechonline.com",
    "Phone: +971 4 234 7770": "Téléphone : +971 4 234 7770",
  
