    "We’ve received your enquiry and our team will contact you shortly with more details.": "Мы получили ваш запрос, и наша команда свяжется с вами в ближайшее время для предоставления дополнительной информации.",
    "Privacy Policy - Skill Tech": "Политика конфиденциальности — Skill Tech",
    "Privacy Policy for Skill Tech Group of Companies.": "Политика конфиденциальности группы компаний Skill Tech.",
    "Effective Date: July 20, 2026": "Дата вступления в силу: 20 июля 2026 г.",
    "At Skill Tech Group of Companies, we are committed to protecting your privacy and safeguarding the personal information you share with us. This Privacy Policy explains how we collect, use, store, and protect your information when you visit www.skilltechonline.com or interact with our services.": "Группа компаний Skill Tech стремится защищать вашу конфиденциальность и оберегать персональные данные, которыми вы делитесь с нами. В настоящей Политике конфиденциальности объясняется, как мы собираем, используем, храним и защищаем вашу информацию, когда вы посещаете сайт www.skilltechonline.com или пользуетесь нашими услугами.",
    "1. Information We Collect": "1. Информация, которую мы собираем",
    "We may collect personal information that you voluntarily provide through our website, including:": "Мы можем собирать персональную информацию, которую вы добровольно предоставляете через наш веб-сайт, включая:",
