    "Any other information you choose to provide": "Любая другая информация, которую вы решите предоставить",
    "2. How We Use Your Information": "2. Как мы используем вашу информацию",
    "Your information is used to:": "Ваша информация используется для:",
    "Respond to enquiries and customer support requests.": "Ответов на запросы и обращений в службу поддержки.",
    "Process installation bookings and service requests.": "Обработки заявок на установку и обслуживание.",
    "Provide product information and quotations.": "Предоставления информации о продуктах и коммерческих предложений.",
    "Review and manage job applications.": "Рассмотрения и управления заявками на трудоустройство.",
    "Improve our website, products, and services.": "Улучшения нашего веб-сайта, продуктов и услуг.",
    "Communicate important updates when necessary.": "Информирования о важных обновлениях при необходимости.",
    "Comply with applicable legal obligations.": "Соблюдения применимых юридических обязательств.",
    "3. Information Sharing": "3. Раскрытие информации",
    "We respect your privacy and do not sell, rent, or trade your personal information. Your information may only be shared with trusted service providers or government authorities when required by law or for the purpose of delivering our services.": "Мы уважаем вашу конфиденциальность и не продаем, не сдаем в аренду и не передаем вашу личную информацию. Ваши данные могут быть переданы только доверенным поставщикам услуг или государственным органам в случаях, предусмотренных законом, или для целей предоставления наших услуг.",
    "4. Data Security": "4. Безопасность данных",
    "We implement appropriate technical and organizational measures to protect your personal information against unauthorized access, misuse, alteration, or disclosure. While we strive to safeguard your data, no internet transmission or electronic storage method can be guaranteed to be completely secure.": "Мы внедряем соответствующие технические и организационные меры для защиты вашей личной информации от несанкционированного доступа, неправомерного использования, изменения или разглашения. Несмотря на то, что мы стремимся обезопасить ваши данные, ни один способ передачи данных через интернет или метод электронного хранения не гарантирует 100% безопасности.",
    "5. Cookies": "5. Файлы cookie",
    "Our website may use cookies and similar technologies to improve your browsing experience, analyze website traffic, and enhance website functionality. You can manage or disable cookies through your browser settings at any time.": "Наш веб-сайт может использовать файлы cookie и аналогичные технологии для улучшения вашего взаимодействия с сайтом, анализа трафика и повышения функциональности. Вы можете в любое время настроить или отключить использование файлов cookie в настройках вашего браузера.",
    "6. Third-Party Links": "6. Сторонние ссылки",
    "Our website may contain links to external websites for your convenience. We are not responsible for the privacy practices or content of these third-party websites and encourage you to review their respective privacy policies.": "Наш веб-сайт может содержать ссылки на сторонние ресурсы для вашего удобства. Мы не несем ответственности за политику конфиденциальности или контент этих сайтов и рекомендуем вам ознакомиться с их правилами обработки данных.",
    "7. Your Rights": "7. Ваши права",
    "You may request access to, correction of, or deletion of your personal information, subject to applicable laws. To make such a request, please contact us using the details below.": "Вы имеете право запросить доступ к вашей личной информации, ее исправление или удаление в соответствии с действующим законодательством. Чтобы подать такой запрос, пожалуйста, свяжитесь с нами, используя контактные данные ниже.",
    "8. Changes to This Policy": "8. Изменения в настоящей Политике",
    "We may update this Privacy Policy from time to time. Any changes will be posted on this page with the revised effective date.": "Мы можем время от времени обновлять данную Политику конфиденциальности. Все изменения будут опубликованы на этой странице с указанием даты вступления в силу.",
    "9. Contact Us": "9. Свяжитесь с нами",
    "If you have any questions regarding this Privacy Policy or how we handle your personal information, please contact us:": "Если у вас есть вопросы относительно данной Политики конфиденциальности или того, как мы обрабатываем ваши данные, пожалуйста, свяжитесь с нами:",
